import{_ as t,o,c as d,a3 as a}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse(`{"title":"Audit log","description":"Wake's audit log of who changed a workspace's people and tokens: how owners read it, download it as CSV, and what it records.","frontmatter":{"description":"Wake's audit log of who changed a workspace's people and tokens: how owners read it, download it as CSV, and what it records."},"headers":[],"relativePath":"use/audit-log.md","filePath":"use/audit-log.md","lastUpdated":1794486787000}`),r={name:"use/audit-log.md"};function n(s,e,c,i,h,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h1><p>Wake keeps a record of who changed a workspace&#39;s people and tokens, written at the moment of each change. Entries are never edited or deleted, and they keep each person&#39;s name and email as they were, even after that person leaves. Changes from before the log existed are not in it.</p><h2 id="read-it" tabindex="-1">Read it <a class="header-anchor" href="#read-it" aria-label="Permalink to &quot;Read it&quot;">​</a></h2><p>Only owners read the log: open <strong>Members</strong> and then <strong>Audit log</strong>. It lists entries newest first, as sentences such as &quot;Ana created an invitation to join as a member&quot;, and <strong>Download CSV</strong> saves them as a spreadsheet file. Members and viewers cannot read or download it.</p><p>Scripts can collect it with a personal access token; see the <a href="/wake-dist/docs/reference/api#audit-log">HTTP API</a>.</p><h2 id="what-it-records" tabindex="-1">What it records <a class="header-anchor" href="#what-it-records" aria-label="Permalink to &quot;What it records&quot;">​</a></h2><p>The download names each change with a code in its <code>action</code> column, and the cause of a revoke in its <code>details</code> column.</p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><code>workspace.created</code></td><td>A workspace is created: your personal one when you sign up, or a team workspace</td></tr><tr><td><code>member.joined</code></td><td>Someone accepts an invitation, with its role</td></tr><tr><td><code>member.removed</code></td><td>An owner removes a member</td></tr><tr><td><code>member.role_changed</code></td><td>An owner changes a role, with <code>from</code> and <code>to</code>; setting the current role records nothing</td></tr><tr><td><code>invitation.created</code></td><td>An owner creates an invitation link, with its role</td></tr><tr><td><code>invitation.revoked</code></td><td>An owner revokes one, or a removal or a step down from owner revokes it</td></tr><tr><td><code>token.created</code></td><td>Someone creates a personal access token, <code>via</code> <code>web</code> or <code>device</code> (a CLI sign-in)</td></tr><tr><td><code>token.revoked</code></td><td>Its holder revokes it, or another change revokes it</td></tr></tbody></table><p>A revoke made directly has the <code>cause</code> <code>direct</code>. One caused by another change names who made that change, with its <code>cause</code>:</p><table tabindex="0"><thead><tr><th>Cause</th><th>The change</th></tr></thead><tbody><tr><td><code>member_removed</code></td><td>An owner removed the member</td></tr><tr><td><code>role_changed</code></td><td>An owner changed the member&#39;s role</td></tr><tr><td><code>signed_out_everywhere</code></td><td>The holder chose <a href="/wake-dist/docs/use/account#sign-out-everywhere">Sign out everywhere</a></td></tr><tr><td><code>account_disabled</code></td><td>Whoever runs the server disabled the account with <code>wake-server accounts disable</code></td></tr></tbody></table><p>A refused change records nothing.</p>',11)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
